    "id": "eshark-run-script-via-globalscriptcontext-emerald",
    "title": "Run script via GlobalScriptContext",
    "author": "final and Mettrich",
    "addedOn": "2026-09-12",
    "summary": "Run script via GlobalScriptContext. This archived output uses the source's published default parameter values.",
    "category": "Utility",
